# ─── parse_rounds ────────────────────────────────────────────────────


def test_parse_rounds_pulls_numeric_token():
    assert parse_rounds("over 2 iteration rounds") == 2
    assert parse_rounds("3 rounds") == 3
    assert parse_rounds("review across 5 rounds please") == 5


def test_parse_rounds_clamps_high_low_and_default():
    assert parse_rounds("twice") == 1  # word "twice" not parsed as numeric
    assert parse_rounds("") == 1
    assert parse_rounds("12345 iteration rounds") == 10  # clamped
    assert parse_rounds("0 rounds") == 1  # clamped to min


# ─── extract_verdict ─────────────────────────────────────────────────


def test_extract_verdict_strict_json():
    r = '{"verdict":"SAFE","blocking_findings":[],"conditions":[],"non_blocking_findings":[],"notes":[]}'
    v, d = extract_verdict(r)
    assert v == "SAFE"
    assert d["verdict"] == "SAFE"


def test_extract_verdict_with_prose_around_json():
    r = 'Here is my review:\n\n{"verdict":"NOT_SAFE","blocking_findings":[{"id":"X1"}]}\n\n<<<DONE>>>'
    v, d = extract_verdict(r)
    assert v == "NOT_SAFE"
    assert d["blocking_findings"][0]["id"] == "X1"


def test_extract_verdict_recovers_invalid_json_via_json_repair():
    # ChatGPT-style: raw 0x0A control character inside a JSON string.
    # Strict json.loads rejects (RFC 8259); json_repair recovers.
    r = '{"verdict":"NOT_SAFE","notes":["line1\nline2\n"]}'
    v, d = extract_verdict(r)
    assert v == "NOT_SAFE"
    # json_repair recovers the full object including notes.
    assert "notes" in d


def test_extract_verdict_plain_text_fallback():
    r = "Decision recorded.\nVERDICT: SAFE_WITH_CONDITIONS\nMore context follows..."
    v, d = extract_verdict(r)
    assert v == "SAFE_WITH_CONDITIONS"
    assert d == {}


def test_extract_verdict_empty_input():
    v, d = extract_verdict("")
    assert v is None
    assert d == {}


def test_extract_verdict_no_match():
    v, d = extract_verdict("This response has no verdict label anywhere.")
    assert v is None


def test_extract_verdict_unknown_label_returns_none():
    r = '{"verdict":"MAYBE"}'
    v, d = extract_verdict(r)
    assert v is None
    # Data still returned so callers can inspect for diagnostics.
    assert d.get("verdict") == "MAYBE"


# ─── build_round1_prompt / build_followup_prompt ─────────────────────


def test_round1_prompt_contains_system_preamble_and_attachment_reference():
    req = WebgptReviewRequest(
        review_type="code",
        description="recent diff",
        diff_scope="HEAD~1..HEAD",
        diff_text="diff --git a/foo b/foo\n",
        max_rounds=1,
    )
    p = build_round1_prompt(req)
    assert "senior code reviewer" in p
    assert "Diff (attached as a Markdown file)" in p
    # The diff text itself MUST NOT be inlined any more — bundle lives in
    # the attached file. Catch a regression that would put us back over
    # the OS argv limit.
    assert "diff --git a/foo b/foo" not in p


def test_followup_prompt_references_prior_blocking_findings():
    prior = RoundResult(
        round_num=1,
        prompt="round1",
        response='{"verdict":"NOT_SAFE","blocking_findings":[{"id":"F1","file":"a.py","lines":"10","summary":"npe"}]}',
        verdict="NOT_SAFE",
        verdict_data={
            "verdict": "NOT_SAFE",
            "blocking_findings": [{"id": "F1", "file": "a.py", "lines": "10", "summary": "npe"}],
        },
        raw_contains_sentinel=True,
        artifact_dir="/tmp/x",
        took_ms=1,
    )
    p = build_followup_prompt(prior, round_num=2, total=2)
    assert "Iteration 2/2" in p
    assert "NOT_SAFE" in p
    assert "npe" in p
    assert "[a.py:10]" in p


# ─── build_review_bundle_file ────────────────────────────────────────


def test_bundle_file_written_with_diff(tmp_path, monkeypatch):
    req = WebgptReviewRequest(
        review_type="code",
        description="recent",
        diff_scope="HEAD~1..HEAD",
        diff_text="diff --git a/x b/x\n@@ +1 @@\n+hi\n",
    )
    p = build_review_bundle_file(req)
    assert p is not None
    text = p.read_text()
    assert "# WebGPT review bundle (code)" in text
    assert "**Diff scope:** `HEAD~1..HEAD`" in text
    assert "diff --git a/x b/x" in text


def test_bundle_file_returns_none_when_nothing_to_bundle():
    req = WebgptReviewRequest(review_type="code", description="just a question")
    assert build_review_bundle_file(req) is None


# ─── resolve_diff bug fix (ASK-WEBGPT-001) ───────────────────────────


def test_resolve_diff_empty_scope_runs_bare_git_diff(monkeypatch):
    """Empty scope means `git diff` with no args (uncommitted only)."""
    captured = {}

    class _FakeResult:
        returncode = 0
        stdout = "diff --git a/uncommitted b/uncommitted\n"

    def fake_run(cmd, **kwargs):
        captured["cmd"] = cmd
        return _FakeResult()

    monkeypatch.setattr("subprocess.run", fake_run)
    out = resolve_diff("")
    # The bug: previous version returned "" immediately on empty scope.
    # Fix: should invoke `git diff --no-color` with no further args.
    assert captured["cmd"][:3] == ["git", "diff", "--no-color"]
    assert len(captured["cmd"]) == 3  # exactly those three, no scope appended
    assert out.startswith("diff --git a/uncommitted")
